import {musicMarkup,bindMusic} from './music.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',translate:'M4 5h12M10 3v2M6 5c0 6 4 9 8 11M14 5c0 6-4 9-10 11M14 21l4-10 4 10M16 17h4',book:'M3 4h6l3 2 3-2h6v15h-6l-3 2-3-2H3z M12 6v15',file:'M5 3h9l5 5v13H5z M14 3v6h5M8 13h8M8 17h6',chat:'M3 4h18v13H9l-6 4z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M5 12h14M14 7l5 5-5 5',upload:'M12 16V3M7 8l5-5 5 5M4 15v6h16v-6',spark:'M12 3l3 6 6 3-6 3-3 6-3-6-6-3 6-3z',check:'M5 12l4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',plus:'M12 5v14M5 12h14',headphones:'M3 14v-3a9 9 0 0 1 18 0v3M3 12h4v9H3z M17 12h4v9h-4z'};
Object.assign(icons,{sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M5 19l1.5-1.5M17.5 6.5L19 5',moon:'M20.5 13A8.5 8.5 0 0 1 11 3.5 8.5 8.5 0 1 0 20.5 13Z',paper:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',stop:'M6 6h12v12H6z'});
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const adminArea=location.pathname==='/admin'||location.pathname.startsWith('/admin/');
const genreDrafts={};
const adminRoutes=new Set(['translate','stories','users','review','requests','settings','glossary']);
function currentRoute(){const route=location.hash.slice(1);return adminArea?(adminRoutes.has(route)?route:'translate'):(['reader','account'].includes(route)?route:'library');}
let state={route:currentRoute(),stories:[],users:[],userStories:[],jobs:[],requests:[],library:[],myLibrary:[],myRequests:[],reader:{authenticated:false},status:{},file:null,pdfAnalysis:null,tab:'file',selected:null,chapters:[],chapter:0,theme:['paper','light','night'].includes(localStorage.getItem('readerTheme'))?localStorage.getItem('readerTheme'):'paper',fontSize:Math.max(16,Math.min(30,Number(localStorage.getItem('readerFontSize'))||19))};let token='',poll=null,busy=false;
async function api(path,options={}){const headers={...(token?{Authorization:`Bearer ${token}`}:{})};if(options.body&&!(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}const r=await fetch('/api'+path,{...options,headers:{...headers,...options.headers}});const d=await r.json();if(!r.ok)throw new Error(d.error||'Kết nối thất bại.');return d;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5500);}
async function refresh(){if(adminArea){state.status=await api('/status');if(state.status.authenticated){[state.stories,state.jobs,state.requests,state.users,state.userStories]=await Promise.all([api('/stories'),api('/jobs'),api('/requests'),api('/users'),api('/user-library')]);}else{state.stories=[];state.jobs=[];state.requests=[];state.users=[];state.userStories=[];}}else{[state.library,state.reader]=await Promise.all([api('/library'),api('/me')]);if(state.reader.authenticated)[state.myLibrary,state.myRequests]=await Promise.all([api('/my/library'),api('/my/requests')]);else{state.myLibrary=[];state.myRequests=[];}}}
function go(route){globalThis.speechSynthesis?.cancel();if(adminArea&&!adminRoutes.has(route)){location.href='/#'+route;return;}state.route=adminArea?(adminRoutes.has(route)?route:'translate'):(['reader','account'].includes(route)?route:'library');location.hash=state.route;render();}
const nav=[['translate','translate','Xưởng dịch'],['stories','book','Kho truyện Cát Hiên'],['users','grid','Độc giả & thư viện riêng'],['review','file','Biên tập bản dịch'],['requests','chat','Yêu cầu độc giả'],['glossary','book','Tên & thuật ngữ']];
function render(){
 if(!adminArea){document.title='Cát Hiên — Đọc truyện';$('#app').innerHTML=publicLayout();bind();return;}
 document.title='Cát Hiên — Quản trị';
 if(!state.status.authenticated){$('#app').innerHTML=loginView();bind();return;}
 const label=nav.find(x=>x[0]===state.route)?.[2]||({settings:'Cài đặt',library:'Thư viện',reader:'Đọc truyện',glossary:'Tên & thuật ngữ'}[state.route])||'Xưởng dịch';
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#translate"><img src="/favicon.svg" alt=""><div><strong>Cát Hiên<span style="color:var(--red)">.</span></strong><small>KHƠI NGUỒN CÂU CHUYỆN</small></div></a><div class="nav-label">QUẢN TRỊ VIÊN</div><nav class="nav" aria-label="Quản lý nội dung">${nav.map(([r,i,t])=>`<button data-route="${r}" class="${state.route===r?'active':''}" ${state.route===r?'aria-current="page"':''}>${icon(i)}${t}${r==='requests'&&state.requests.filter(x=>x.status==='pending').length?`<span class="count">${state.requests.filter(x=>x.status==='pending').length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="engine"><strong style="font-size:12px">${icon('spark')} &nbsp; Gemini Flash</strong><p><span class="dot" style="background:${state.status.aiConfigured?'#7e9169':'#bb9b60'}"></span>${state.status.aiConfigured?'Sẵn sàng dịch thuật':'Chờ kết nối API'}<br>Ngữ cảnh liền mạch. Tên nhất quán.</p></div><nav class="nav" aria-label="Hệ thống"><button data-route="settings" class="${state.route==='settings'?'active':''}">${icon('settings')}Cài đặt</button><button id="admin-logout">${icon('arrow')}Đăng xuất</button></nav><div class="profile"><span class="avatar">CH</span><div style="font-size:12px">Không gian biên tập<small>${state.status.authenticated?'Quản trị viên':'Chưa đăng nhập'}</small></div></div></div></aside><main class="main"><header class="topbar"><span>Khu quản trị <span style="margin-left:14px">/</span><b>${label}</b></span><a href="/">Xem trang đọc truyện ${icon('arrow')}</a></header><div class="content">${view()}<footer class="footer"><span>CÁT HIÊN &nbsp; / &nbsp; Mỗi câu chữ, một hành trình.</span><span>Trung văn → Việt ngữ</span></footer></div></main></div>`;bind();}
function bookIcon(){return 'book'}
function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="subtitle">${desc}</p></div>${action}</div>`;}
function view(){switch(state.route){case 'translate':return translateView();case 'review':return reviewView();case 'stories':return storiesView();case 'users':return usersView();case 'requests':return requestsView();case 'settings':return settingsView();case 'glossary':return glossaryView();case 'library':return libraryView();case 'reader':return readerView();default:return translateView();}}
function storyOptions(){const option=s=>`<option value="${s.id}" ${s.id===state.storyId?'selected':''}>${esc(s.title)}</option>`,web=state.stories.filter(s=>!s.owner_user_id),personal=state.stories.filter(s=>s.owner_user_id);return `${web.length?`<optgroup label="Kho Cát Hiên">${web.map(option).join('')}</optgroup>`:''}${personal.length?`<optgroup label="Sách của độc giả">${personal.map(s=>`<option value="${s.id}" ${s.id===state.storyId?'selected':''}>${esc(s.title)} · ${esc(s.owner_name||s.owner_email||'Độc giả')}</option>`).join('')}</optgroup>`:''}`;}
function translateView(){return heading('XƯỞNG DỊCH AI','Từ nguyên tác đến bản dịch.','Đưa những câu chuyện vượt qua ranh giới ngôn ngữ.',`<div class="button-row"><button data-route="review">${icon('clock')} &nbsp; Lịch sử dịch</button></div>`)+`<div class="stats">${[['file','Tài liệu đã tải',state.jobs.length,'tài liệu'],['translate','Chờ biên tập',state.jobs.filter(j=>j.status==='review').length,'bản dịch'],['book','Đã xuất bản',state.jobs.filter(j=>j.status==='published').length,'chương truyện'],['chat','Yêu cầu mới',state.requests.filter(r=>r.status==='pending').length,'từ độc giả']].map(([i,t,n,s])=>`<div class="stat"><div class="stat-top">${t}${icon(i)}</div><strong>${n.toString().padStart(2,'0')}</strong><small>${s}</small></div>`).join('')}</div><div class="workspace"><section class="panel"><div class="panel-heading"><h2>Tạo bản dịch mới</h2><span class="step-label">01 / TÀI LIỆU NGUỒN</span></div><div class="tabs"><button class="${state.tab==='file'?'active':''}" data-tab="file">${icon('upload')} &nbsp; Tải tài liệu</button><button class="${state.tab==='text'?'active':''}" data-tab="text">${icon('file')} &nbsp; Nhập văn bản</button></div><div class="upload-area">${state.tab==='file'?`<div class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="Chọn tài liệu để dịch"><div class="upload-symbol">${icon('upload')}</div><strong>Kéo thả tài liệu của bạn vào đây</strong><p>hoặc chọn tệp từ máy tính để bắt đầu</p><button id="pick-file" type="button">Chọn tài liệu ${icon('plus')}</button><div class="formats"><span>PDF</span><span>DOCX</span><span>EPUB</span><span>JPG / PNG</span><span>TXT</span><span>TỐI ĐA 25 MB</span></div><p class="upload-limit">TXT / DOCX / EPUB dài được tự động chia nhỏ để dịch. EPUB giữ thứ tự chương, không hỗ trợ nội dung khóa DRM. TXT: UTF-8 hoặc UTF-16 có BOM.</p></div><input class="hide" type="file" id="file-input" accept=".pdf,.epub,.docx,.png,.jpg,.jpeg,.webp,.txt">${state.file?`<div class="selected-file">${icon('file')}<span>${esc(state.file.name)} <small>· ${(state.file.size/1024).toFixed(0)} KB</small></span><button id="remove-file" style="margin-left:auto;padding:4px 8px" aria-label="Bỏ tệp">×</button></div>`:''}`:`<label>Nguyên tác tiếng Trung<textarea id="source-input" rows="9" maxlength="25000000" placeholder="Dán nội dung tiếng Trung vào đây…">${esc(state.draftText||'')}</textarea></label>`}</div><div class="form-grid"><label>Bộ truyện<select id="story-select"><option value="">Chọn bộ truyện…</option>${storyOptions()}</select></label><label>Thể loại<select id="genre"><option>Tu tiên</option><option>Tiên hiệp</option><option>Kiếm hiệp</option><option>Ngôn tình</option><option>Lịch sử · Cổ văn</option><option>Hiện đại</option><option>Khác</option></select></label><div class="field-wide"><button id="new-story" style="border:0;background:none;color:var(--red);padding:0;font-size:11px">+ Tạo bộ truyện mới</button></div><div class="field-wide" id="story-cover-slot">${uploadCoverPanel()}</div></div><div class="upload-footer"><small>${icon('check')} &nbsp; Bản dịch luôn được duyệt trước khi đăng</small><div class="upload-actions"><button id="prepare-pdf" ${!state.file?.name.toLowerCase().endsWith(".pdf")?"disabled":""}>Chia PDF trước</button><button class="primary" id="start-translate">${icon('spark')} &nbsp; Bắt đầu dịch</button></div></div></section><aside class="panel aside-panel"><h3>${icon('settings')} Hỗ trợ bản dịch</h3><div class="language-pair" aria-label="Dịch từ tiếng Trung sang tiếng Việt"><div><small>Nguyên tác</small><strong>中文 · Tiếng Trung</strong></div>${icon('arrow')}<div><small>Bản dịch</small><strong>Tiếng Việt</strong></div></div><div class="toggle-row"><div><strong>Giữ nhất quán tên nhân vật</strong><p>Dùng bảng tên xuyên suốt bộ truyện.</p></div><span class="feature-status">${icon('check')}<span>Tự động</span></span></div><div class="toggle-row"><div><strong>Phục hồi chữ từ sách cũ</strong><p>Nhận diện chữ phồn thể, cột dọc và đánh dấu chữ mờ.</p></div><span class="feature-status">${icon('check')}<span>Tự động</span></span></div><div class="note">${icon('spark')} &nbsp; AI phân tích bối cảnh và cách xưng hô trước khi dịch. Chữ chưa rõ được giữ để bạn đối chiếu.</div><div class="process"><h3 style="font-size:12px;margin:0">QUY TRÌNH DỊCH</h3><p><i>1</i>Chia PDF · 2 trang mỗi phần</p><p><i>2</i>OCR & dịch lần lượt từng phần</p><p><i>3</i>Ghép đủ các phần thành quyển</p><p><i>4</i>Biên tập & xuất bản</p></div></aside></div><section class="recent"><div class="section-title"><h2>Tài liệu gần đây <span class="muted" style="font-size:12px">&nbsp; ${state.jobs.length}</span></h2><button data-route="review">Xem tất cả &nbsp; →</button></div>${jobsTable(state.jobs.slice(0,4))}</section>`;}
const statuses={uploaded:'Đã tải lên',splitting:'Đang chia PDF',prepared:'Đã chia · Sẵn sàng dịch',assembling:'Đang ghép thành quyển',ocr:'Đang OCR',translating:'Đang dịch',review:'Chờ biên tập',published:'Đã xuất bản',failed:'Cần xử lý'};
function jobsTable(jobs){return `<div class="panel table-wrap"><table><thead><tr><th>TÀI LIỆU</th><th>BỘ TRUYỆN</th><th>TRẠNG THÁI</th><th>NGÀY TẢI</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td><div class="file-cell"><span class="file-icon">${icon('file')}</span><strong>${esc(j.filename)}</strong></div></td><td>${esc(j.story_title)}</td><td><span class="badge ${j.status==='review'?'review':j.status==='failed'?'failed':''}">${statuses[j.status]}</span></td><td class="muted">${esc(j.created_at?.slice(0,10))}</td><td><button data-job="${j.id}" style="padding:6px 10px;border:0" aria-label="Mở ${esc(j.filename)}">→</button><button class="danger" data-delete-job="${j.id}" ${busy?"disabled":""}>Xóa</button></td></tr>`).join('')}</tbody></table>${!jobs.length?`<div class="empty">${icon('file')} &nbsp; Chưa có tài liệu. Tải lên bản nguyên tác đầu tiên để bắt đầu.</div>`:''}</div>`;}
function reviewView(){const j=state.jobs.find(j=>j.id===state.selected);if(!j)return heading('BIÊN TẬP','Mỗi câu chữ đều xứng đáng.','Đối chiếu nguyên tác, chỉnh bản dịch và duyệt trước khi xuất bản.')+jobsTable(state.jobs);return heading('BẢN ĐỐI CHIẾU',esc(j.story_title),esc(j.filename))+`<div class="button-row"><button id="back-jobs">← Danh sách</button>${j.file_key?'<button id="download-original">Tải bản gốc</button>':''}${j.mime==='application/pdf'?'<button id="pdf-parts">Các phần PDF</button>':''}${['review','published'].includes(j.status)?'<button id="download-book">Tải cả quyển (.txt)</button>':''}<span class="badge">${statuses[j.status]}</span><button id="rerun" ${busy||j.status==='published'?'disabled':''}>${icon('spark')} ${['uploaded','prepared'].includes(j.status)?'Bắt đầu dịch':['failed','splitting','ocr','translating','assembling'].includes(j.status)?'Tiếp tục xử lý':'Dịch lại'}</button><button class="danger" data-delete-job="${j.id}" ${busy?"disabled":""}>Xóa tài liệu</button><button id="save-job" ${j.source_key||j.translation_key||busy||['splitting','prepared','ocr','translating','assembling','published'].includes(j.status)||(j.status==='failed'&&j.progress)?'disabled':''}>Lưu biên tập</button><button class="primary" id="publish-job" ${j.status!=='review'?'disabled':''}>Duyệt & đăng chương</button></div>${j.source_key||j.translation_key?'<p class="note" style="margin-top:16px">Văn bản dài: ô bên dưới hiển thị 20.000 ký tự đầu. Bản đầy đủ được lưu riêng, không bị cắt. <button id="download-source">Tải nguyên tác đầy đủ</button></p>':''}${j.progress?`<p class="note" style="margin-top:16px">${esc(j.progress)}${['review','published'].includes(j.status)?'':' · Giữ trang mở khi xử lý; có thể tiếp tục sau nếu đóng trang.'}</p>`:''}${j.error?`<div class="warning">${esc(j.error)}</div>`:''}${JSON.parse(j.warnings||'[]').length?`<div class="warning">${JSON.parse(j.warnings).map(esc).join('<br>')}</div>`:''}<div class="editor-grid"><section class="panel aside-panel"><h3>中文 &nbsp; Nguyên tác / OCR</h3><textarea id="edit-source" ${j.source_key||j.translation_key||busy||['splitting','prepared','ocr','translating','assembling','published'].includes(j.status)||(j.status==='failed'&&j.progress)?'readonly':''}>${esc(j.source)}</textarea></section><section class="panel aside-panel"><h3>Tiếng Việt &nbsp; · &nbsp; Bản dịch</h3><textarea id="edit-translation" ${j.source_key||j.translation_key||busy||['splitting','prepared','ocr','translating','assembling','published'].includes(j.status)||(j.status==='failed'&&j.progress)?'readonly':''} placeholder="Bản dịch xuất hiện sau khi Gemini xử lý hoàn tất.">${esc(j.translation)}</textarea></section></div>`;}
function adminStoryCard(s,owner=''){return `<article class="panel book story-card"><details class="story-actions"><summary aria-label="Mở thao tác cho ${esc(s.title)}" title="Quản lý truyện">${icon('settings')}</summary><div class="story-actions-menu"><button data-story="${s.id}">${icon('translate')} Dịch chương mới</button><button data-rename-story="${s.id}">${icon('file')} Đổi tên truyện</button><button data-ai-cover="${s.id}">${icon('spark')} Tạo bìa AI</button><button data-cover="${s.id}">${icon('upload')} ${s.cover_key?'Đổi ảnh bìa':'Tải ảnh bìa'}</button><button data-import="${s.id}">${icon('book')} Tải bản đọc lên</button><button data-chapters="${s.id}">${icon('grid')} Chương đã đăng</button><button class="danger" data-delete-story="${s.id}">${icon('plus')} Xóa truyện</button></div></details>${coverArt(s)}${owner?`<span class="owner-chip">${icon('book')} ${esc(owner)}</span>`:''}<h2>${esc(s.title)}</h2><p>${esc(s.author||'Chưa cập nhật')} · ${esc(s.genre)}</p><p><strong>${Number(s.chapters)||0}</strong> chương đã đăng · ${state.jobs.filter(j=>j.story_id===s.id).length} tài liệu dịch</p></article>`;}
function storiesView(){const webStories=state.stories.filter(s=>!s.owner_user_id);return heading('KHO NỘI DUNG CÁT HIÊN','Kho truyện của website','Chỉ hiển thị các bộ truyện thuộc thư viện chung do Cát Hiên quản lý.',`<div class="button-row"><button id="import-website">Nhập từ website</button><button id="import-chapter">Tải truyện lên thư viện</button><button class="primary" id="new-story">+ Tạo bộ truyện</button></div>`)+`<div class="collection-summary"><span>${icon('book')} ${webStories.length} bộ truyện của website</span><span>${icon('grid')} ${webStories.reduce((sum,s)=>sum+Number(s.chapters||0),0)} chương đã đăng</span></div><div class="library">${webStories.map(s=>adminStoryCard(s)).join('')}</div>${!webStories.length?'<div class="panel empty">Kho Cát Hiên chưa có bộ truyện nào.</div>':''}`;}
function usersView(){return heading('TÀI KHOẢN ĐỘC GIẢ','Độc giả & thư viện riêng','Theo dõi tài khoản, yêu cầu dịch và sách thuộc từng độc giả.')+`<div class="user-stats"><div class="panel"><strong>${state.users.length}</strong><span>Tài khoản</span></div><div class="panel"><strong>${state.userStories.length}</strong><span>Sách của độc giả</span></div><div class="panel"><strong>${state.requests.filter(r=>r.status==='pending').length}</strong><span>Yêu cầu đang chờ</span></div></div><div class="user-management">${state.users.map(user=>{const books=state.userStories.filter(s=>s.owner_user_id===user.id),requests=state.requests.filter(r=>r.user_id===user.id);return `<section class="panel user-block"><header><div class="user-identity">${user.picture?`<img src="${esc(user.picture)}" alt="">`:'<span>'+esc((user.name||user.email).slice(0,1).toUpperCase())+'</span>'}<div><h2>${esc(user.name||'Chưa đặt tên')}</h2><p>${esc(user.email)}</p></div></div><div class="user-badges"><span>${user.provider==='google'?'Google':'Cát Hiên'}</span><span>${books.length} sách</span><span>${requests.length} yêu cầu</span></div></header><div class="user-request-line">${requests.length?`Yêu cầu gần nhất: <strong>${esc(requests[0].title)}</strong> · ${({pending:'đang chờ',accepted:'đang dịch',done:'hoàn tất'})[requests[0].status]}`:'Chưa gửi yêu cầu dịch.'}</div><div class="user-books">${books.map(s=>adminStoryCard(s,s.visibility==='public'?'Đã chia sẻ':'Thư viện riêng')).join('')||'<div class="empty">Độc giả này chưa có sách.</div>'}</div></section>`;}).join('')}</div>${!state.users.length?'<div class="panel empty">Chưa có tài khoản độc giả.</div>':''}`;}
function requestsView(){return heading('LẮNG NGHE ĐỘC GIẢ','Những câu chuyện được mong đợi.','Tiếp nhận đề xuất và đưa nguyên tác vào xưởng dịch.')+`<div class="library">${state.requests.map(r=>`<article class="panel book"><div class="request-meta"><span class="badge">${({pending:'Mới',accepted:'Đang tiếp nhận',done:'Đã hoàn tất'})[r.status]}</span><span class="privacy-badge">${r.visibility==='public'?'Thư viện chung':'Riêng tư'}</span></div><h2 style="margin-top:16px">${esc(r.title)}</h2><p class="subtitle">${esc(r.reader_name||r.reader_email||'Độc giả cũ')}</p><p>${esc(r.notes)}</p><div class="request-links">${r.source_url?`<a href="${esc(r.source_url)}" target="_blank" rel="noopener noreferrer">Xem nguồn ↗</a>`:''}${r.filename?`<button type="button" class="link-button" data-request-file="${r.id}">Tải tệp · ${esc(r.filename)}</button>`:''}</div><div class="button-row" style="margin-top:20px"><button data-accept="${r.id}" ${r.story_id?'disabled':''}>${r.story_id?'Đã tạo truyện':'Tiếp nhận & tạo truyện'}</button><button data-done="${r.id}">Hoàn tất</button><button class="danger" data-delete-request="${r.id}">Xóa</button></div></article>`).join('')}</div>${!state.requests.length?'<div class="panel empty">Chưa có yêu cầu mới từ độc giả.</div>':''}`;}
function settingsView(){return heading('KẾT NỐI','Cài đặt không gian dịch','Khóa Gemini được giữ trên máy chủ, không gửi xuống trình duyệt.')+`<section class="panel aside-panel" style="max-width:650px"><h3>Truy cập quản trị</h3><label>Mã quản trị<input type="password" id="admin-token" placeholder="Nhập ADMIN_TOKEN đã cấu hình trên máy chủ" autocomplete="off"></label><button class="primary" id="login" style="margin-top:18px">Kết nối</button><button id="logout" style="margin-left:8px">Đăng xuất</button><p class="subtitle">Mã chỉ giữ trong bộ nhớ của phiên hiện tại.</p><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>Gemini Flash</h3><p class="subtitle">Model: ${esc(state.status.model||'gemini-2.5-flash')}<br>${state.status.aiConfigured?'Đã cấu hình khóa API.':'Chưa có khóa API. Điền GEMINI_API_KEY trong .dev.vars khi chạy cục bộ hoặc biến môi trường máy chủ khi triển khai.'}<br>${state.status.adminConfigured?'Mã quản trị đã được cấu hình.':'Cần cấu hình ADMIN_TOKEN trên máy chủ trước khi đăng nhập.'}</p></section>`;}
function glossaryView(){return heading('NHẤT QUÁN XUYÊN SUỐT','Tên & thuật ngữ','Tên chưa có quy ước sẽ được giữ nguyên chữ Trung. Bạn có thể đặt tên Việt cố định.')+`<div class="panel aside-panel"><label>Bộ truyện<select id="glossary-story"><option value="">Chọn bộ truyện</option>${state.stories.map(s=>`<option value="${s.id}" ${state.glossaryId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label style="margin-top:20px">Mỗi dòng: tên tiếng Trung = tên dùng trong bản dịch<textarea id="glossary-text" rows="12" placeholder="林风 = Lâm Phong">${esc(Object.entries(JSON.parse(state.stories.find(s=>s.id===state.glossaryId)?.glossary||'{}')).map(([k,v])=>`${k} = ${v}`).join('\n'))}</textarea></label><button id="save-glossary" class="primary" style="margin-top:18px">Lưu bảng tên</button></div>`;}
function libraryView(){return `<section class="library-intro"><div class="library-ornament" aria-hidden="true"><span></span><i>書</i><span></span></div><p class="eyebrow">THƯ VIỆN CÁT HIÊN</p><p class="library-chinese" lang="zh-Hant">一卷書 · 一方天地</p><h1>Một trang sách, một thế giới.</h1><p class="subtitle">Chọn một bìa sách để khám phá câu chuyện.</p><div class="library-seal" aria-hidden="true">吉<br>軒</div><div class="library-filters"><label class="library-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="library-search" type="search" aria-label="Tìm tên sách hoặc tác giả" placeholder="Tìm tên sách, tác giả…" value="${esc(state.libraryQuery||'')}"></label><div class="genre-filter" role="group" aria-label="Lọc thể loại">${['',...new Set(state.library.map(s=>s.genre).filter(Boolean))].map(g=>`<button type="button" data-library-genre="${esc(g)}" aria-pressed="${(state.libraryGenre||'')===g}">${esc(g||'Tất cả')}</button>`).join('')}</div></div><p class="library-result-count" id="library-result-count" role="status"></p></section><div class="cover-library">${state.library.map((s,i)=>`<article class="cover-book" data-library-index="${i}"><button class="cover-trigger" aria-label="Thông tin sách ${esc(s.title)}" aria-expanded="false" aria-controls="book-info-${i}">${coverArt(s)}</button><div class="book-reveal" id="book-info-${i}"><small class="book-genre">${esc(s.genre||'Truyện')}</small><h2>${esc(s.title)}</h2><p class="book-author">Tác giả: ${esc(s.author||'Chưa cập nhật')}</p><p class="book-chapters">${icon('book')} ${Number(s.chapters)||0} chương đã đăng</p><button class="primary" data-read="${s.id}">Bắt đầu đọc ${icon('arrow')}</button></div></article>`).join('')}</div><div id="library-no-results" class="empty" hidden>Không tìm thấy sách phù hợp. Hãy thử từ khóa hoặc thể loại khác.</div>${!state.library.length?'<div class="panel empty">Thư viện đang chờ những chương đầu tiên.<br>Bạn có thể gửi yêu cầu truyện muốn đọc.</div>':''}`;}
function personalBookCards(){return state.myLibrary.map((s,i)=>`<article class="personal-book">${coverArt(s)}<div><span class="privacy-badge">${s.visibility==='public'?'Đã chia sẻ':'Riêng tư'}</span><h3>${esc(s.title)}</h3><p>${esc(s.genre)} · ${Number(s.chapters)||0} chương</p>${Number(s.chapters)?`<button class="primary" data-read="${s.id}">Đọc sách ${icon('arrow')}</button>`:'<small>Ban biên tập đang chuẩn bị chương đầu tiên.</small>'}</div></article>`).join('');}
function accountView(){if(!state.reader.authenticated)return `<section class="account-auth"><div class="auth-intro"><p class="eyebrow">GÓC ĐỘC GIẢ</p><h1>Thư viện của riêng bạn</h1><p>Tạo tài khoản Cát Hiên để gửi yêu cầu, theo dõi tiến độ và đọc truyện riêng tư.</p><div class="auth-benefits"><span>${icon('book')} Thư viện cá nhân</span><span>${icon('chat')} Theo dõi yêu cầu</span><span>${icon('check')} Nội dung riêng tư</span></div></div><div class="auth-forms panel"><div class="auth-tabs" role="tablist"><button type="button" class="active" data-auth-tab="login">Đăng nhập</button><button type="button" data-auth-tab="register">Tạo tài khoản</button></div><form id="reader-login-form" class="auth-form"><label>Email<input name="email" type="email" autocomplete="email" required maxlength="320"></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" required minlength="8" maxlength="128"></label><button class="primary" type="submit">Đăng nhập</button></form><form id="reader-register-form" class="auth-form" hidden><label>Tên hiển thị<input name="name" autocomplete="name" required maxlength="100"></label><label>Email<input name="email" type="email" autocomplete="email" required maxlength="320"></label><label>Mật khẩu<input name="password" type="password" autocomplete="new-password" required minlength="8" maxlength="128"><small>Từ 8 đến 128 ký tự.</small></label><button class="primary" type="submit">Tạo tài khoản</button></form>${state.reader.googleConfigured?`<div class="auth-divider"><span>hoặc</span></div><a class="google-login" href="/api/auth/google/start?return_to=${encodeURIComponent('/#account')}"><span>G</span> Tiếp tục bằng Google</a>`:'<p class="google-later">Đăng nhập Google sẽ xuất hiện khi được cấu hình.</p>'}</div></section>`;const u=state.reader.user;return `<section class="account-heading"><div class="account-profile">${u.picture?`<img src="${esc(u.picture)}" alt="">`:'<span>讀</span>'}<div><p class="eyebrow">GÓC ĐỘC GIẢ</p><h1>${esc(u.name||'Thư viện của tôi')}</h1><p>${esc(u.email)}</p></div></div><button id="reader-logout">Đăng xuất</button></section><section class="personal-section"><div class="section-title"><h2>Thư viện riêng</h2><button id="account-request">+ Yêu cầu truyện</button></div><div class="personal-library">${personalBookCards()||'<div class="panel empty">Chưa có truyện trong thư viện cá nhân.</div>'}</div></section><section class="personal-section"><h2>Yêu cầu của tôi</h2><div class="my-requests">${state.myRequests.map(r=>`<article class="panel request-row"><div><span class="badge">${({pending:'Đang chờ',accepted:'Đang dịch',done:'Hoàn tất'})[r.status]}</span><span class="privacy-badge">${r.visibility==='public'?'Chia sẻ chung':'Riêng tư'}</span></div><h3>${esc(r.title)}</h3><p>${r.filename?`Tệp: ${esc(r.filename)}`:r.source_url?'Đã gửi liên kết nguyên tác':'Nguồn chưa cập nhật'} · ${esc(r.created_at?.slice(0,10))}</p>${r.story_id?'<small>Truyện đã được đưa vào thư viện của bạn.</small>':''}</article>`).join('')||'<div class="panel empty">Bạn chưa gửi yêu cầu nào.</div>'}</div></section>`;}

function readerView(){
 const c=state.chapters[state.chapter];if(!c)return '<div class="empty">Chọn một truyện trong thư viện để đọc.</div>';
 const pdf=c.mime==='application/pdf';
 return `<div class="reader-layout"><div class="reader-toolbar" aria-label="Công cụ đọc truyện">
 <button class="reader-back" data-route="library" title="Về thư viện">${icon('book')}<span>Thư viện</span></button>
 <label class="reader-chapter-picker"><span>Chương</span><select id="reader-chapter-select" aria-label="Chọn chương đang đọc">${state.chapters.map((chapter,index)=>`<option value="${index}" ${index===state.chapter?'selected':''}>${index+1}. ${esc(chapter.title)}</option>`).join('')}</select></label>
 <div class="reader-options"><div class="reader-control-group theme-options" role="group" aria-label="Màu trang sách">${[['paper','paper','Màu giấy'],['light','sun','Nền sáng'],['night','moon','Ban đêm']].map(([theme,glyph,label])=>`<button class="reader-icon theme-${theme}" data-reader-theme="${theme}" aria-label="${label}" title="${label}" aria-pressed="${state.theme===theme}">${icon(glyph)}</button>`).join('')}</div>
 ${!pdf?`<div class="reader-control-group font-options" role="group" aria-label="Cỡ chữ"><button class="reader-icon" id="font-smaller" title="Giảm cỡ chữ" aria-label="Giảm cỡ chữ" ${state.fontSize<=16?'disabled':''}><span class="font-symbol">A−</span></button><output class="font-value" aria-live="polite" aria-label="Cỡ chữ hiện tại">${state.fontSize}</output><button class="reader-icon" id="font-larger" title="Tăng cỡ chữ" aria-label="Tăng cỡ chữ" ${state.fontSize>=30?'disabled':''}><span class="font-symbol">A+</span></button></div>`:''}</div>
 ${!pdf?`<div class="reader-audio" role="group" aria-label="Đọc thành tiếng"><button class="reader-icon listen-icon" id="speak" aria-label="Nghe đọc tiếng Việt" title="Nghe đọc tiếng Việt">${icon('headphones')}</button><button class="reader-icon stop-icon" id="stop-speak" aria-label="Dừng nghe" title="Dừng nghe">${icon('stop')}</button></div>`:''}
 </div><article class="reader ${state.theme}"><p class="eyebrow">CHƯƠNG ${state.chapter+1} / ${state.chapters.length}</p><h1>${esc(c.title)}</h1>${c.source_url?`<p class="chapter-source">Nguồn: <a href="${esc(c.source_url)}" target="_blank" rel="noopener noreferrer">TruyenXin.top ↗</a></p>`:''}${pdf?`<p class="subtitle">Tài liệu PDF · <a href="/api/chapter-file/${encodeURIComponent(c.id)}" target="_blank" rel="noopener">Mở PDF trong tab mới ↗</a></p><iframe class="reader-pdf" title="${esc(c.title)}" src="/api/chapter-file/${encodeURIComponent(c.id)}"></iframe>`:`<div class="prose" style="font-size:${state.fontSize}px">${esc(c.content)}</div>`}</article>
 <nav class="reader-pagination" aria-label="Chuyển chương"><button id="prev-chapter" ${state.chapter===0?'disabled':''}>← <span>Chương trước</span></button><span class="chapter-position">${state.chapter+1}<small> / ${state.chapters.length}</small></span><button id="next-chapter" ${state.chapter===state.chapters.length-1?'disabled':''}><span>Chương tiếp</span> →</button></nav></div>`;
}

function on(sel,event,fn){$(sel)?.addEventListener(event,async e=>{try{await fn(e);}catch(error){toast(error.message);}})}
function modal(html,submit,confirmLabel='Xác nhận'){const d=$('#modal');if(d.open)d.close();d.innerHTML=`<form id="modal-form">${html}<div class="button-row"><button type="button" id="close-modal">Hủy</button><button class="primary">${esc(confirmLabel)}</button></div></form>`;d.showModal();$('#close-modal').onclick=()=>d.close();$('#modal-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await submit(new FormData(e.target));d.close();}catch(err){toast(err.message);}finally{button.disabled=false;}};}

function chooseChapter(storyId){
 const story=[...state.library,...state.myLibrary].find(item=>item.id===storyId);
 return api(`/read/${storyId}`).then(chapters=>{
  if(!chapters.length)throw new Error('Truyện này chưa có chương để đọc.');
  state.chapters=chapters;
  modal(`<div class="chapter-choice-heading"><p class="eyebrow">${esc(story?.title||'MỤC LỤC')}</p><h2>Chọn chương bắt đầu</h2><p class="subtitle">${chapters.length} chương đã đăng</p></div><label class="chapter-search">Tìm chương<input id="chapter-search-input" type="search" placeholder="Nhập số hoặc tên chương…" autocomplete="off"></label><label class="chapter-choice-label">Danh sách chương<select name="chapter" id="chapter-start-select" size="${Math.min(9,chapters.length)}" required>${chapters.map((chapter,index)=>`<option value="${index}" ${index===0?'selected':''}>${index+1}. ${esc(chapter.title)}</option>`).join('')}</select></label><p id="chapter-search-empty" class="subtitle" hidden>Không tìm thấy chương phù hợp.</p>`,form=>{openReaderWithBookAnimation(story,Number(form.get('chapter')));},'Mở sách');
  on('#chapter-search-input','input',event=>{const query=normalizeLibraryText(event.target.value),select=$('#chapter-start-select');let visible=0;for(const option of select.options){const matches=normalizeLibraryText(option.textContent).includes(query);option.hidden=!matches;if(matches)visible++;}if(select.selectedOptions[0]?.hidden)select.value=Array.from(select.options).find(option=>!option.hidden)?.value||'';$('#chapter-search-empty').hidden=visible>0;});
 });
}

function openReaderWithBookAnimation(story,chapterIndex){
 state.chapter=chapterIndex;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){go('reader');return;}
 document.querySelector('.book-opening-overlay')?.remove();
 const cover=story?.cover_key?`<img src="/api/covers/${encodeURIComponent(story.id)}?v=${encodeURIComponent(story.cover_key)}" alt="">`:`<div class="opening-cover-placeholder">${esc(story?.title?.slice(0,1)||'書')}</div>`;
 const overlay=document.createElement('div');overlay.className='book-opening-overlay';overlay.setAttribute('aria-hidden','true');overlay.innerHTML=`<div class="opening-light"></div><div class="opening-book"><div class="opening-pages opening-pages-left"><span></span><span></span><span></span></div><div class="opening-pages opening-pages-right"><span></span><span></span><span></span></div><div class="opening-book-cover">${cover}<div class="opening-cover-shade"></div><strong>${esc(story?.title||'Cát Hiên')}</strong></div><div class="opening-book-spine"></div></div><p class="opening-caption">Đang mở · ${esc(state.chapters[chapterIndex]?.title||'Chương truyện')}</p>`;document.body.append(overlay);
 requestAnimationFrame(()=>overlay.classList.add('is-opening'));
 setTimeout(()=>{go('reader');overlay.classList.add('is-finished');},1050);
 setTimeout(()=>overlay.remove(),1500);
}
function createStory(){modal(`<h2>Tạo bộ truyện</h2><label>Tên truyện<input name="title" required maxlength="200"></label><label style="margin-top:16px">Thể loại<select name="genre"><option>Tu tiên</option><option>Tiên hiệp</option><option>Kiếm hiệp</option><option>Ngôn tình</option><option>Lịch sử · Cổ văn</option><option>Hiện đại</option><option>Khác</option></select></label>${coverInput()}`,async f=>{const r=await api('/stories',{method:'POST',body:f});state.storyId=r.id;await refresh();render();toast('Đã tạo bộ truyện.');});bindCoverPreview();}
async function runJob(jid){busy=true;go('review');state.selected=jid;render();toast('Đang nhận diện và dịch. Bạn có thể theo dõi trạng thái tại đây.');poll=setInterval(async()=>{try{state.jobs=await api('/jobs');if(state.route==='review')render();}catch{}},4000);try{let result;do{result=await api(`/jobs/${jid}/run`,{method:'POST'});state.jobs=state.jobs.map(j=>j.id===jid?{...j,...result}:j);if(state.route==='review')render();}while(token&&['splitting','prepared','assembling','ocr','translating','uploaded'].includes(result.status));}finally{busy=false;clearInterval(poll);await refresh();render();}}
function requestStory(){if(!state.reader.authenticated){go('account');toast('Hãy đăng nhập hoặc tạo tài khoản để gửi yêu cầu.');return;}modal(`<div class="request-form-heading"><p class="eyebrow">GỬI NGUYÊN TÁC</p><h2>Bạn muốn Cát Hiên dịch truyện nào?</h2><p class="subtitle">Tải tệp trực tiếp hoặc gửi liên kết. Chỉ cần một trong hai nguồn.</p></div><label>Tên truyện<input name="title" required maxlength="200"></label><label class="request-file" style="margin-top:15px">Tệp nguyên tác<input name="file" type="file" accept=".pdf,.epub,.azw3,.docx,.txt,.jpg,.jpeg,.png,.webp"><small>PDF, EPUB, AZW3, DOCX, TXT hoặc ảnh · tối đa 25 MB</small></label><label style="margin-top:15px">Liên kết nguyên tác <small>(không bắt buộc)</small><input name="source_url" type="url" placeholder="https://…"></label><label style="margin-top:15px">Lời nhắn<textarea name="notes" maxlength="2000" rows="3" placeholder="Tên tác giả, lưu ý về bản dịch…"></textarea></label><fieldset class="visibility-choice"><legend>Ai có thể đọc khi truyện hoàn thành?</legend><label><input type="radio" name="visibility" value="private" checked><span>${icon('book')}<strong>Chỉ mình tôi</strong><small>Lưu trong thư viện riêng</small></span></label><label><input type="radio" name="visibility" value="public"><span>${icon('spark')}<strong>Chia sẻ cộng đồng</strong><small>Đưa vào thư viện chung</small></span></label></fieldset>`,async f=>{const file=f.get('file'),source=String(f.get('source_url')||'').trim();if(file?.size>25*1024*1024)throw new Error('Tệp yêu cầu tối đa 25 MB.');if(!file?.size&&!source)throw new Error('Hãy chọn một tệp hoặc nhập liên kết nguyên tác.');await api('/requests',{method:'POST',body:f});await refresh();render();toast('Đã gửi yêu cầu. Bạn có thể theo dõi tiến độ tại đây.');},'Gửi yêu cầu');}
function bind(){bindMusic(toast);document.querySelectorAll('[data-auth-tab]').forEach(button=>button.onclick=()=>{const register=button.dataset.authTab==='register';document.querySelectorAll('[data-auth-tab]').forEach(item=>item.classList.toggle('active',item===button));$('#reader-login-form').hidden=register;$('#reader-register-form').hidden=!register;});on('#reader-login-form','submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);await api('/auth/login',{method:'POST',body:Object.fromEntries(form)});await refresh();render();toast('Đăng nhập thành công.');});on('#reader-register-form','submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);await api('/auth/register',{method:'POST',body:Object.fromEntries(form)});await refresh();render();toast('Tài khoản đã được tạo.');});document.querySelectorAll('[data-request-file]').forEach(b=>b.onclick=async()=>{const r=await fetch(`/api/requests/${b.dataset.requestFile}/file`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw new Error('Không tải được tệp nguồn.');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=state.requests.find(x=>x.id===b.dataset.requestFile)?.filename||'nguyen-tac';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});on('#download-source','click',async()=>{const r=await fetch(`/api/jobs/${state.selected}/source`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw new Error('Không tải được nguyên tác.');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='nguyen-tac.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});bindAdminContent();on('#pdf-parts','click',showPdfParts);on('#download-book','click',downloadBook);bindCoverButtons();on('#reader-request','click',requestStory);on('#account-request','click',requestStory);on('#reader-logout','click',async()=>{await fetch('/api/auth/logout',{method:'POST'});await refresh();go('library');toast('Đã đăng xuất tài khoản độc giả.');});on('#admin-login-form','submit',e=>e.preventDefault());document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.draftText=$('#source-input')?.value||state.draftText;state.storyId=$('#story-select')?.value;state.tab=b.dataset.tab;render();});document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.job;go('review');});
 const translationInput=$('#file-input');if(translationInput){translationInput.accept+=',.azw3';const formats=$('.formats');if(formats&&!formats.textContent.includes('AZW3'))formats.querySelector('span:last-child')?.insertAdjacentHTML('beforebegin','<span>AZW3</span>');}
 on('#new-story','click',createStory);on('#back-jobs','click',()=>{state.selected=null;render();});on('#story-select','change',e=>{state.storyId=e.target.value;const s=state.stories.find(s=>s.id===state.storyId);$('#genre').value=genreDrafts[state.storyId]||s?.genre||'Tiên hiệp';$('#story-cover-slot').innerHTML=uploadCoverPanel();bindCoverButtons();});if($('#genre'))$('#genre').value=genreDrafts[state.storyId||'']||state.stories.find(s=>s.id===state.storyId)?.genre||'Tiên hiệp';on('#genre','change',e=>{genreDrafts[state.storyId||'']=e.target.value;});
 async function selected(file){if(!file)return;if(file.size>25*1024*1024)throw new Error('Tối đa 25 MB mỗi tài liệu.');state.file=file;state.pdfAnalysis=null;state.storyId=$('#story-select')?.value;render();if(file.name.toLowerCase().endsWith('.pdf')){toast('Đang kiểm tra lớp chữ của PDF trên trình duyệt…');try{const {analyzePdf}=await import('./pdf-client.js');state.pdfAnalysis=await analyzePdf(file,(page,total)=>{if(page===1||page===total||page%10===0)toast(`Đang phân tích PDF · ${page}/${total} trang`);});toast(state.pdfAnalysis.mode==='text'?`Đã lấy và làm sạch lớp chữ từ ${state.pdfAnalysis.totalPages} trang. Không cần OCR ảnh.`:`Đã nhận diện PDF scan ${state.pdfAnalysis.totalPages} trang. Ảnh sẽ được giảm còn 1200px, chuyển xám và nén trước khi OCR.`);}catch(error){state.pdfAnalysis={mode:'fallback',error:error.message};toast('Không đọc được lớp chữ trong trình duyệt; máy chủ sẽ dùng quy trình PDF dự phòng.');}render();}}
 on('#dropzone','click',e=>{e.preventDefault();$('#file-input').click();});on('#dropzone','keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file-input').click();}});on('#file-input','change',e=>selected(e.target.files[0]));on('#dropzone','dragover',e=>{e.preventDefault();e.currentTarget.classList.add('drag');});on('#dropzone','dragleave',e=>e.currentTarget.classList.remove('drag'));on('#dropzone','drop',e=>{e.preventDefault();selected(e.dataTransfer.files[0]);});on('#remove-file','click',()=>{state.file=null;render();});
 on('#start-translate','click',e=>uploadJob(e,false));on('#prepare-pdf','click',e=>uploadJob(e,true));
 on('#login','click',async e=>{e.preventDefault();token=$('#admin-token').value;try{await refresh();if(!state.status.authenticated)throw new Error('Mã quản trị không đúng.');go('translate');toast('Đã kết nối không gian quản trị.');}catch(e){token='';state.status={authenticated:false};state.jobs=[];state.stories=[];state.requests=[];render();throw e;}});on('#logout','click',logout);on('#admin-logout','click',logout);
 on('#rerun','click',()=>runJob(state.selected));on('#save-job','click',async()=>{await api(`/jobs/${state.selected}`,{method:'PATCH',body:{source:$('#edit-source').value,translation:$('#edit-translation').value}});await refresh();render();toast('Đã lưu bản biên tập.');});
 on('#publish-job','click',()=>{const source=$('#edit-source').value,translation=$('#edit-translation').value;modal('<h2>Duyệt & đăng chương</h2><label>Tên chương<input name="title" required maxlength="200" placeholder="Chương 1: Khởi đầu"></label><label class="confirm-check"><input type="checkbox" name="confirmed" required> Tôi đã đối chiếu bản dịch và kiểm tra những chữ chưa rõ.</label>',async f=>{if(!state.jobs.find(j=>j.id===state.selected)?.source_key&&!state.jobs.find(j=>j.id===state.selected)?.translation_key)await api(`/jobs/${state.selected}`,{method:'PATCH',body:{source,translation}});await api(`/jobs/${state.selected}/publish`,{method:'POST',body:{title:f.get('title'),confirmed:true}});await refresh();render();toast('Chương đã được đăng lên thư viện.');});});
 on('#download-original','click',async()=>{const r=await fetch(`/api/jobs/${state.selected}/file`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw new Error('Không tải được bản gốc.');const a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download=state.jobs.find(j=>j.id===state.selected).filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});
 document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{state.storyId=b.dataset.story;go('translate');});on('#glossary-story','change',e=>{state.glossaryId=e.target.value;render();});on('#save-glossary','click',async()=>{if(!state.glossaryId)throw new Error('Chọn bộ truyện.');const glossary={};for(const line of $('#glossary-text').value.split('\n').filter(x=>x.trim())){const i=line.indexOf('=');if(i<1||!line.slice(i+1).trim())throw new Error('Mỗi dòng cần có dạng: tên Trung = tên dịch');glossary[line.slice(0,i).trim()]=line.slice(i+1).trim();}await api(`/stories/${state.glossaryId}`,{method:'PATCH',body:{glossary}});await refresh();toast('Đã lưu bảng tên. Áp dụng cho những lần dịch tiếp theo.');});
 document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{try{const r=state.requests.find(r=>r.id===b.dataset.accept);let story=state.stories.find(s=>s.id===r.story_id);if(!story)story=await api('/stories',{method:'POST',body:{title:r.title,genre:'Khác',owner_user_id:r.user_id,visibility:r.visibility}});await api(`/requests/${r.id}`,{method:'PATCH',body:{status:'accepted',story_id:story.id}});state.storyId=story.id;await refresh();go('translate');toast(r.filename?'Đã tiếp nhận. Tải tệp nguồn từ yêu cầu rồi đưa vào xưởng dịch.':'Đã tiếp nhận yêu cầu dịch.');}catch(e){toast(e.message);}});document.querySelectorAll('[data-done]').forEach(b=>b.onclick=async()=>{try{await api(`/requests/${b.dataset.done}`,{method:'PATCH',body:{status:'done'}});await refresh();render();}catch(e){toast(e.message);}});
 document.querySelectorAll('.cover-trigger').forEach(b=>b.onclick=()=>{const card=b.closest('.cover-book');const open=card.classList.toggle('is-open');b.setAttribute('aria-expanded',String(open));});
 on('#library-search','input',e=>{state.libraryQuery=e.target.value;filterLibrary();});document.querySelectorAll('[data-library-genre]').forEach(b=>b.onclick=()=>{state.libraryGenre=b.dataset.libraryGenre;filterLibrary();});filterLibrary();document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>chooseChapter(b.dataset.read).catch(e=>toast(e.message)));document.querySelectorAll('[data-reader-theme]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.readerTheme;localStorage.setItem('readerTheme',state.theme);render();});on('#reader-chapter-select','change',e=>{globalThis.speechSynthesis?.cancel();state.chapter=Number(e.target.value);render();scrollTo({top:0,behavior:'smooth'});});on('#font-smaller','click',()=>changeReaderFont(-1));on('#font-larger','click',()=>changeReaderFont(1));on('#prev-chapter','click',()=>{speechSynthesis.cancel();state.chapter--;render();});on('#next-chapter','click',()=>{speechSynthesis.cancel();state.chapter++;render();});on('#stop-speak','click',()=>speechSynthesis.cancel());on('#speak','click',()=>{if(state.chapters[state.chapter]?.mime==='application/pdf')throw new Error('PDF được đọc trong khung tài liệu; chức năng giọng đọc dành cho chương văn bản.');if(!('speechSynthesis'in window))throw new Error('Trình duyệt không hỗ trợ đọc giọng máy.');const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('vi'));if(!voice)throw new Error('Chưa có giọng tiếng Việt trên thiết bị. Hãy cài giọng tiếng Việt trong hệ điều hành.');speechSynthesis.cancel();const paragraphs=state.chapters[state.chapter].content.match(/[\s\S]{1,200}[.!?\n\s]|[\s\S]+$/g)||[];for(const p of paragraphs){const u=new SpeechSynthesisUtterance(p);u.voice=voice;u.lang='vi-VN';speechSynthesis.speak(u);}});
}
window.addEventListener('hashchange',()=>{state.route=currentRoute();render();});render();refresh().then(render).catch(e=>toast('Chưa tải được dữ liệu: '+e.message));
if(adminArea&&document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_translation_workspace',description:'Mở xưởng dịch; không tải tệp hoặc gọi AI.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!state.status.authenticated)throw new Error('Cần đăng nhập quản trị.');if(!input||Object.keys(input).length)throw new Error('Không nhận tham số.');go('translate');return{route:'translate'};}});}catch{}}

function publicLayout(){const user=state.reader.user;return `<div class="public-shell">${state.route==='library'?homeAtmosphere():''}<header class="public-header"><a class="brand" href="/"><img src="/favicon.svg" alt=""><div><strong>Cát Hiên<span style="color:var(--red)">.</span></strong><small>KHƠI NGUỒN CÂU CHUYỆN</small></div></a><div class="header-floating-title" tabindex="0" aria-label="Cát Hiên · 吉軒"><span aria-hidden="true">${Array.from('吉軒 · Cát Hiên').map((letter,i)=>`<span class="floating-letter" style="--letter-index:${i}">${letter===' '?'&nbsp;':esc(letter)}</span>`).join('')}</span></div><nav aria-label="Dành cho độc giả"><a href="/#library">${icon('book')} Thư viện</a><button id="reader-request">${icon('plus')} Yêu cầu truyện</button>${state.reader.authenticated?`<a class="reader-account-link" href="/#account">${user.picture?`<img src="${esc(user.picture)}" alt="">`:icon('book')}<span>${esc(user.name?.split(' ')[0]||'Của tôi')}</span></a>`:`<a class="reader-login-link" href="/#account">Đăng nhập</a>`}</nav></header><main class="public-content ${state.route==='reader'?'read-mode':''} ${state.route==='account'?'account-mode':''}">${state.route==='reader'?readerView():state.route==='account'?accountView():libraryView()}</main>${musicMarkup()}<footer class="public-footer">CÁT HIÊN · Mỗi câu chữ, một hành trình.</footer></div>`;}
function loginView(){return `<main class="admin-login"><a class="login-back" href="/">← Về thư viện độc giả</a><section class="panel login-card"><p class="eyebrow">KHU VỰC QUẢN TRỊ</p><h1>Đăng nhập quản trị</h1><p class="subtitle">Dịch tài liệu, biên tập và xuất bản truyện.</p><form id="admin-login-form"><label for="admin-token">Mã quản trị</label><input type="password" id="admin-token" autocomplete="current-password" required placeholder="Nhập mã quản trị"><button class="primary" id="login" type="submit">Đăng nhập</button></form></section></main>`;}
async function logout(){token='';clearInterval(poll);state.status={authenticated:false};state.jobs=[];state.stories=[];state.requests=[];state.file=null;state.selected=null;state.draftText='';$('#modal').close();go('settings');}

function coverArt(s){return s.cover_key?`<img class="book-cover" src="/api/covers/${encodeURIComponent(s.id)}?v=${encodeURIComponent(s.cover_key)}" alt="Bìa ${esc(s.title)}" loading="lazy">`:`<div class="book-art cover-placeholder"><span>${esc(s.title.slice(0,1))}</span><small>Chưa có ảnh bìa</small></div>`;}
function uploadCoverPanel(){const s=state.stories.find(s=>s.id===state.storyId);return s?`<div class="upload-cover">${coverArt(s)}<div><strong>Ảnh bìa bộ truyện</strong><p class="subtitle">Hiển thị cùng truyện trong thư viện độc giả.</p><button type="button" data-cover="${s.id}">${s.cover_key?'Đổi ảnh bìa':'Tải ảnh bìa'}</button></div></div>`:'';}
function coverInput(){return `<label style="margin-top:18px">Ảnh bìa truyện<input type="file" name="cover" id="cover-input" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG, WebP · tối đa 5 MB · nên dùng ảnh dọc 2:3.</small></label><img id="cover-preview" class="cover-preview hide" alt="Xem trước ảnh bìa">`;}
function bindCoverPreview(){let previewUrl;const dialog=$('#modal');dialog.addEventListener('close',()=>{if(previewUrl)URL.revokeObjectURL(previewUrl);},{once:true});on('#cover-input','change',e=>{if(previewUrl)URL.revokeObjectURL(previewUrl);const image=$('#cover-preview');image.classList.add('hide');image.removeAttribute('src');const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){e.target.value='';throw new Error('Chọn ảnh JPG, PNG hoặc WebP tối đa 5 MB.');}previewUrl=URL.createObjectURL(file);image.src=previewUrl;image.classList.remove('hide');});}
function bindCoverButtons(){document.querySelectorAll('[data-cover]').forEach(b=>b.onclick=()=>{state.draftText=$('#source-input')?.value??state.draftText;const sid=b.dataset.cover;modal(`<h2>Ảnh bìa bộ truyện</h2>${coverInput()}`,async form=>{if(!form.get('cover')?.size)throw new Error('Hãy chọn ảnh bìa.');await api(`/stories/${sid}/cover`,{method:'POST',body:form});await refresh();render();toast('Đã lưu ảnh bìa.');});bindCoverPreview();});document.querySelectorAll('[data-ai-cover]').forEach(b=>b.onclick=()=>generateAiCover(b.dataset.aiCover));}
function generateAiCover(sid){const story=state.stories.find(item=>item.id===sid);if(!story)return;modal(`<h2>Tạo bìa bằng AI</h2><p class="subtitle">Gemini sẽ dùng tên truyện, thể loại, bối cảnh và chương đầu để tạo ảnh dọc 2:3 cho <strong>${esc(story.title)}</strong>. Ảnh hiện tại sẽ được thay thế sau khi tạo xong.</p><div class="note">Ảnh AI không chứa tiêu đề để tránh lỗi chữ. Bạn có thể tạo lại hoặc tải ảnh thủ công nếu chưa phù hợp.</div>`,async()=>{toast('Đang tạo ảnh bìa, quá trình có thể mất khoảng một phút…');await api(`/stories/${sid}/generate-cover`,{method:'POST'});await refresh();render();toast('Đã tạo và lưu ảnh bìa AI.');});}

async function uploadJob(e,prepareOnly){const sid=$('#story-select').value;if(!sid)throw new Error('Hãy tạo hoặc chọn bộ truyện trước.');const f=new FormData(),sourceFile=state.file,pdfAnalysis=state.pdfAnalysis;f.set('story_id',sid);if(state.tab==='file'){if(!sourceFile)throw new Error('Hãy chọn tài liệu.');if(sourceFile.name.toLowerCase().endsWith('.pdf')&&!pdfAnalysis)throw new Error('Hãy đợi phân tích PDF hoàn tất.');f.set('file',sourceFile);if(pdfAnalysis?.mode==='text'){f.set('parsed_text',pdfAnalysis.text);f.set('pdf_pages',String(pdfAnalysis.totalPages));}if(pdfAnalysis?.mode==='scan'){f.set('pdf_mode','scan');f.set('pdf_pages',String(pdfAnalysis.totalPages));}}else f.set('text',$('#source-input').value);const genre=$('#genre').value;e.currentTarget.disabled=true;try{if(genre!==state.stories.find(s=>s.id===sid)?.genre){await api(`/stories/${sid}`,{method:'PATCH',body:{genre}});const story=state.stories.find(s=>s.id===sid);if(story)story.genre=genre;}const j=await api('/jobs',{method:'POST',body:f});state.selected=j.id;if(pdfAnalysis?.mode==='scan'){const {uploadOptimizedScan}=await import('./pdf-client.js');await uploadOptimizedScan(sourceFile,async(blob,page,total)=>{const pageForm=new FormData();pageForm.set('page',String(page));pageForm.set('total',String(total));pageForm.set('image',blob,`page-${page}.${blob.type==='image/webp'?'webp':'jpg'}`);await api(`/jobs/${j.id}/pdf-page`,{method:'POST',body:pageForm});},(page,total)=>toast(`Đang tối ưu PDF scan · ${page}/${total} trang`));}state.file=null;state.pdfAnalysis=null;await refresh();go('review');if(prepareOnly)await prepareJob(j.id);else if(state.status.aiConfigured)await runJob(j.id);else toast('Đã lưu tài liệu. Cấu hình khóa Gemini trong máy chủ để bắt đầu dịch.');}finally{if($('#start-translate'))$('#start-translate').disabled=false;}}

async function prepareJob(jid){busy=true;try{let result;do{result=await api(`/jobs/${jid}/prepare`,{method:'POST'});state.jobs=state.jobs.map(j=>j.id===jid?{...j,...result}:j);render();}while(token&&result.status==='splitting');if(result.status==='prepared')toast('Đã chia xong PDF. Bấm Bắt đầu dịch khi sẵn sàng.');}finally{busy=false;await refresh();render();}}
async function showPdfParts(){const data=await api(`/jobs/${state.selected}/parts`);modal(`<h2>Các phần PDF</h2><p class="subtitle">${data.totalPages?`${data.totalPages} trang · ${data.parts.length} phần đã chia · ${data.pagesPerPart} trang/phần`:'PDF chưa được chia. Bấm Bắt đầu dịch để tự động chia trước.'}</p><p class="subtitle">Các phần sẽ được dịch và ghép theo thứ tự trang, giữ chung ngữ cảnh và bảng tên.</p><ol class="pdf-parts">${data.parts.map(p=>`<li>Phần ${p.index+1} <span>Trang ${p.startPage}–${p.endPage}</span></li>`).join('')}</ol>`,async()=>{});}
async function downloadBook(){const r=await fetch(`/api/jobs/${state.selected}/book`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok){const data=await r.json();throw new Error(data.error);}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(state.jobs.find(j=>j.id===state.selected)?.story_title||'ban-dich')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function bindAdminContent(){
 on('#import-website','click',importFromWebsite);
 on('#import-chapter','click',()=>importChapter());
 document.querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>importChapter(b.dataset.import));
 document.querySelectorAll('[data-chapters]').forEach(b=>b.onclick=()=>showChapters(b.dataset.chapters).catch(e=>toast(e.message)));
 document.querySelectorAll('[data-rename-story]').forEach(b=>b.onclick=()=>renameStory(b.dataset.renameStory));
 for(const [kind,field,collection,label,details] of [['job','deleteJob',state.jobs,'tài liệu','Bản gốc, phần PDF đã chia, bản dịch và chương đăng từ tài liệu này sẽ bị xóa.'],['story','deleteStory',state.stories,'bộ truyện','Toàn bộ chương, tài liệu, bản dịch và ảnh bìa của truyện sẽ bị xóa khỏi thư viện.'],['request','deleteRequest',state.requests,'yêu cầu','Yêu cầu của độc giả sẽ bị xóa.']]){
  document.querySelectorAll(`[data-delete-${kind}]`).forEach(b=>b.onclick=()=>{const item=collection.find(x=>x.id===b.dataset[field]);confirmDelete(kind,item?.id,item?.title||item?.filename||label,details);});
 }
}
function confirmDelete(kind,id,title,details){
 if(!id)return;const endpoints={job:'jobs',story:'stories',request:'requests',chapter:'chapters'};
 modal(`<h2>Xóa ${esc(title)}?</h2><p class="subtitle">${esc(details)} Thao tác này không thể hoàn tác.</p><label class="confirm-check"><input type="checkbox" required> Tôi xác nhận xóa nội dung này.</label>`,async()=>{await api(`/${endpoints[kind]}/${id}`,{method:'DELETE'});if(kind==='job'&&state.selected===id)state.selected=null;if(kind==='story'){state.selected=null;if(state.storyId===id)state.storyId='';}await refresh();render();toast('Đã xóa.');});
}
async function showChapters(sid){
 const chapters=await api(`/stories/${sid}/chapters`);
 modal(`<h2>Chương đã đăng</h2><p class="subtitle">${chapters.length} chương · sắp xếp theo thứ tự đọc</p><div class="chapter-admin-list">${chapters.map((c,index)=>`<div><span class="chapter-admin-number">${String(index+1).padStart(2,'0')}</span><span class="chapter-admin-title"><strong>${esc(c.title)}</strong><small>${c.mime==='application/pdf'?'PDF':'Văn bản'}</small></span><button type="button" class="danger" data-delete-chapter="${c.id}">Xóa chương</button></div>`).join('')||'<p class="empty">Chưa có chương. Dùng Tải bản đọc lên để thêm nội dung.</p>'}</div>`,async()=>{});
 document.querySelectorAll('[data-delete-chapter]').forEach(b=>b.onclick=()=>{const chapter=chapters.find(c=>c.id===b.dataset.deleteChapter);confirmDelete('chapter',chapter.id,chapter.title,'Chương sẽ được gỡ khỏi thư viện. Bản dịch trong xưởng (nếu có) vẫn được giữ để đăng lại.');});
}
function renameStory(sid){
 const story=state.stories.find(item=>item.id===sid);if(!story)return;
 modal(`<h2>Đổi tên truyện</h2><p class="subtitle">Tên mới sẽ được cập nhật trong quản trị, tài liệu dịch và thư viện độc giả.</p><label>Tên truyện<input name="title" value="${esc(story.title)}" required minlength="1" maxlength="200" autocomplete="off"></label>`,async form=>{const title=String(form.get('title')||'').trim();await api(`/stories/${sid}`,{method:'PATCH',body:{title}});await refresh();render();toast('Đã đổi tên truyện.');},'Lưu tên mới');
 setTimeout(()=>$('#modal input[name="title"]')?.select());
}
function importFromWebsite(){
 const example='https://www.truyenxin.top/search/label/truy%E1%BB%87n%20tu%20ti%C3%AAn';
 modal(`<h2>Nhập truyện từ TruyenXin</h2><p class="subtitle">Dán đường dẫn danh mục Truyện Tu Tiên hoặc đường dẫn một bộ truyện AX. Hệ thống sẽ đọc feed công khai và cho bạn kiểm tra trước.</p><label>Đường dẫn nguồn<input name="source_url" id="web-source-url" type="url" required value="${example}"></label><button type="button" id="web-preview" style="margin-top:14px">Kiểm tra nguồn</button><div id="web-preview-result" class="web-preview-result"><p class="subtitle">Chưa kiểm tra nguồn.</p></div><label>Tác giả<input name="author" maxlength="120" placeholder="Tên tác giả; có thể cập nhật sau"></label><label>Thể loại<select name="genre"><option>Tu tiên</option><option>Tiên hiệp</option><option>Kiếm hiệp</option><option>Ngôn tình</option><option>Lịch sử · Cổ văn</option><option>Hiện đại</option><option>Khác</option></select></label><label class="confirm-check"><input name="confirmed" value="true" type="checkbox" required> Tôi xác nhận mình có quyền sử dụng và đăng lại nội dung từ nguồn này.</label>`,async form=>{
  const selected=$('#web-series-select');if(!selected?.value)throw new Error('Hãy kiểm tra nguồn và chọn một bộ truyện trước.');
  const option=selected.selectedOptions[0],result=await api('/web-import',{method:'POST',body:{source_url:form.get('source_url'),label:selected.value,title:option.dataset.title,author:form.get('author'),genre:form.get('genre'),confirmed:form.get('confirmed')==='true'}});
  await refresh();render();toast(`Đã nhập ${result.chapters} chương của ${result.title}.`);
 });
 on('#web-preview','click',async()=>{
  const button=$('#web-preview'),box=$('#web-preview-result');button.disabled=true;box.innerHTML='<p class="subtitle">Đang đọc danh sách từ trang nguồn…</p>';
  try{
   const data=await api('/web-import/preview',{method:'POST',body:{source_url:$('#web-source-url').value}}),series=data.type==='series'?[{...data.series,chapters:data.series.chapters.length,url:$('#web-source-url').value}]:data.series;
   if(!series.length){box.innerHTML='<p class="warning">Không tìm thấy bộ truyện phù hợp.</p>';return;}
   box.innerHTML=`<label>Chọn bộ truyện<select id="web-series-select" required>${series.map(item=>`<option value="${esc(item.label)}" data-title="${esc(item.title)}">${esc(item.title)} · ${item.chapters} chương</option>`).join('')}</select></label><p class="note">Nội dung sẽ được nhập thẳng vào thư viện và giữ đường dẫn nguồn ở từng chương.</p>`;
  }finally{button.disabled=false;}
 });
}
function importChapter(sid){
 if(!state.stories.length){toast('Hãy tạo bộ truyện trước khi tải bản đọc lên.');createStory();return;}
 modal(`<h2>Tải truyện lên thư viện</h2><p class="subtitle">Đăng bản tiếng Việt đã có sẵn để độc giả đọc ngay. TXT / DOCX hiển thị thành văn bản; PDF mở trong khung đọc.</p><label>Bộ truyện<select name="story_id">${state.stories.map(s=>`<option value="${s.id}" ${s.id===sid?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>Tên chương / quyển<input name="title" required maxlength="200"></label><label>Tệp bản đọc<input id="publication-file" name="file" type="file" accept=".txt,.docx,.pdf" required><small>Tối đa 25 MB. TXT dùng UTF-8; văn bản tối đa 500.000 ký tự.</small></label><p id="import-status" class="subtitle">Chọn tệp để xem trước.</p><label id="publication-text-label" class="hide">Nội dung (có thể biên tập)<textarea name="content" id="publication-text" rows="9"></textarea></label><iframe id="publication-pdf" class="reader-pdf hide" title="Xem trước PDF"></iframe><label class="confirm-check"><input name="confirmed" value="true" type="checkbox" required> Tôi đã kiểm tra nội dung và đồng ý đăng cho độc giả.</label>`,async form=>{if(!ready)throw new Error('Hãy đợi xem trước tài liệu hoàn tất.');await api(`/stories/${form.get('story_id')}/chapters`,{method:'POST',body:form});await refresh();render();toast('Đã đăng lên thư viện. Độc giả có thể đọc ngay.');});
 let ready=false,sequence=0,previewUrl;
 $('#modal').addEventListener('close',()=>{sequence++;if(previewUrl)URL.revokeObjectURL(previewUrl);},{once:true});
 on('#publication-file','change',async e=>{
  ready=false;const current=++sequence,file=e.target.files[0];$('#publication-text-label').classList.add('hide');$('#publication-pdf').classList.add('hide');$('#publication-text').value='';if(previewUrl)URL.revokeObjectURL(previewUrl);if(!file)return;
  $('#import-status').textContent='Đang đọc tệp để xem trước…';const form=new FormData();form.set('file',file);
  try{const data=await api('/import-preview',{method:'POST',body:form});if(current!==sequence)return;
   if(data.mime==='application/pdf'){previewUrl=URL.createObjectURL(file);$('#publication-pdf').src=previewUrl;$('#publication-pdf').classList.remove('hide');}
   else{$('#publication-text').value=data.content;$('#publication-text-label').classList.remove('hide');}
   $('#import-status').textContent='Đã đọc tệp. Kiểm tra nội dung trước khi đăng.';ready=true;
  }catch(error){if(current===sequence)$('#import-status').textContent='Không đọc được tệp: '+error.message;}
 });
}

function changeReaderFont(delta){state.fontSize=Math.max(16,Math.min(30,state.fontSize+delta));localStorage.setItem('readerFontSize',String(state.fontSize));const prose=$('.prose');if(prose)prose.style.fontSize=state.fontSize+'px';const value=$('.font-value');if(value)value.textContent=state.fontSize;$('#font-smaller').disabled=state.fontSize<=16;$('#font-larger').disabled=state.fontSize>=30;}

function normalizeLibraryText(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().trim();}
function filterLibrary(){
 const counter=$('#library-result-count');if(!counter)return;
 const query=normalizeLibraryText(state.libraryQuery);let count=0;
 document.querySelectorAll('[data-library-index]').forEach(card=>{const book=state.library[Number(card.dataset.libraryIndex)];const matches=(!state.libraryGenre||book.genre===state.libraryGenre)&&normalizeLibraryText(`${book.title} ${book.author||''}`).includes(query);card.hidden=!matches;if(matches)count++;});
 document.querySelectorAll('[data-library-genre]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.libraryGenre===(state.libraryGenre||''))));
 counter.textContent=`${count} / ${state.library.length} bộ truyện`;
 $('#library-no-results').hidden=count>0||state.library.length===0;
}

function homeAtmosphere(){return `<div class="home-atmosphere" aria-hidden="true">${Array.from({length:7},(_,i)=>`<svg class="drifting-leaf" style="--leaf:${i};left:${8+i*14}%" viewBox="0 0 60 24"><path d="M2 21Q18-8 58 3Q39 30 2 21Z" fill="currentColor"/><path d="M3 21 54 5" stroke="#edf0df" stroke-width=".8"/></svg>`).join('')}<div class="mist mist-one"></div><div class="mist mist-two"></div></div>`;}


